{"code":"import os
import re

root = r"C:\AI\benchmark\v2\results-uzak-bishop-p1\sandboxes\qwen3.5-9b__off\term-ini\servisler"

# Dosyaları bul (yedek hariç)
for root_dir, dirs, files in os.walk(root):
    if 'yedek' in root_dir:
        dirs.remove('yedek')
        continue
    for f in files:
        if f.endswith('.ini'):
            filepath = os.path.join(root_dir, f)
            # Dosyayı binary olarak oku (BOM ve satır sonlarını koru)
            with open(filepath, 'rb') as file:
                content = file.read()

            # UTF-8 BOM varsa
            has_bom = content.startswith(b'\xef\xbb\xbf')
            original_content = content

            line_ending = b'\r\n' if b'\r\n' in content else b'\n'
            ends_with_ending = content.endswith(line_ending)
            lines = content.split(line_ending)

            new_lines = []
            in_veritabani = False

            for line in lines:
                # Bölüm başlığını bul (büyük/küçük harf duyarsız)
                match = re.search(rb'\[(veritabani)\]', line, re.IGNORECASE)
                if match:
                    in_veritabani = True
                    new_lines.append(line)
                elif in_veritabani:
                    # Yorum satırı mı?
                    stripped = line.strip()
                    if stripped.startswith(b';'):
                        new_lines.append(line)
                    # port satırı mı? (boşluklarla da eşleşsin)
                    elif re.search(rb'port\s*=', line):
                        # [veritabani] bölümündeki port=5432'yi değiştir
                        if b'5432' in line:
                            # port=5432 veya port = 5432 şeklinde değiştir
                            new_lines.append(line.replace(b'5432', b'6543'))
                        else:
                            new_lines.append(line)
                    else:
                        new_lines.append(line)
                else:
                    new_lines.append(line)

            new_content = line_ending.join(new_lines)

            # BOM ekle
            if has_bom:
                new_content = b'\xef\xbb\xbf' + new_content

            if original_content != new_content:
                with open(filepath, 'wb') as file:
                    file.write(new_content)
                print(f"Değiştirildi: {filepath}")
            else:
                print(f"Değişiklik yok: {filepath}")

print("\nİşlem tamamlandı.")"}
